import React, { useState, useEffect } from 'react';
import { Menu, X, Instagram, Mail, Heart } from 'lucide-react';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    setIsOpen(false);

    const targetId = href.replace('#', '');
    const element = document.getElementById(targetId);

    if (element) {
        const headerOffset = 100;
        const elementPosition = element.getBoundingClientRect().top;
        const offsetPosition = elementPosition + window.scrollY - headerOffset;

        window.scrollTo({
            top: offsetPosition,
            behavior: "smooth"
        });

        window.history.pushState(null, '', href);
    }
  };

  const navLinks = [
    { name: 'Studio', href: '#studio', num: '01' },
    { name: 'Portfolio', href: '#work', num: '02' },
    { name: 'Leistungen', href: '#services', num: '03' },
    { name: 'Kontakt', href: '#contact', num: '04' },
  ];

  return (
    <nav
      className={`fixed top-0 left-0 w-full z-[100] transition-all duration-1000 ease-in-out ${
        isScrolled 
            ? 'bg-[#F9F9F7]/80 backdrop-blur-2xl py-4 border-b border-black/5' 
            : 'bg-transparent py-10'
      }`}
    >
      <div className="container mx-auto px-6 md:px-12 flex justify-between items-center">

        {/* Logo */}
        <a href="#" onClick={(e) => { e.preventDefault(); window.scrollTo({top: 0, behavior: 'smooth'}); }} className="relative z-[150] flex items-baseline gap-1 group">
          <span className={`text-2xl md:text-3xl font-serif tracking-tighter transition-colors duration-500 ${
            isOpen || isScrolled ? 'text-black' : 'text-white'
          }`}>AK</span>
          <span className={`text-[9px] uppercase tracking-[0.4em] font-medium transition-colors duration-500 ${
            isOpen || isScrolled ? 'text-gray-400' : 'text-gray-300'
          }`}>Studio</span>
        </a>

        {/* Desktop Menu */}
        <div className="hidden md:flex items-center gap-16">
            <div className="flex space-x-12">
                {navLinks.map((link) => (
                    <a
                      key={link.name}
                      href={link.href}
                      onClick={(e) => scrollToSection(e, link.href)}
                      className={`text-[10px] uppercase tracking-[0.3em] font-semibold relative group transition-colors duration-500 ${
                        isScrolled ? 'text-gray-500 hover:text-black' : 'text-gray-200 hover:text-white'
                        }`}
                    >
                      {link.name}
                      <span className="absolute -bottom-1 left-0 w-0 h-[1px] bg-brand transition-all duration-500 group-hover:w-full"></span>
                    </a>
                ))}
            </div>

            <div className="flex items-center gap-6">
                 <a href="https://instagram.com/akfilmstudio" target="_blank" className={`transition-all duration-500 hover:scale-110 ${isScrolled ? 'text-gray-400 hover:text-brand' : 'text-white/60 hover:text-white'}`}>
                    <Instagram size={16} strokeWidth={1.5} />
                 </a>
                 <div className={`w-[1px] h-4 ${isScrolled ? 'bg-gray-200' : 'bg-white/20'}`}></div>
                 <a href="#contact" onClick={(e) => scrollToSection(e, '#contact')} className={`px-6 py-2 text-[10px] uppercase tracking-[0.2em] font-bold border transition-all duration-500 rounded-full ${
                   isScrolled ? 'border-brand text-brand hover:bg-brand hover:text-white' : 'border-white/30 text-white hover:bg-white hover:text-black'
                 }`}>
                   Anfrage
                 </a>
            </div>
        </div>

        {/* Mobile Toggle */}
        <button
          onClick={() => setIsOpen(!isOpen)}
          className="md:hidden z-[150] relative p-2"
          aria-label="Toggle Menu"
        >
          <div className="w-6 h-5 flex flex-col justify-between items-end">
            <span className={`h-[1px] bg-current transition-all duration-500 ${isOpen ? 'w-6 translate-y-2 -rotate-45' : 'w-6'} ${isOpen || isScrolled ? 'text-black' : 'text-white'}`}></span>
            <span className={`h-[1px] bg-current transition-all duration-500 ${isOpen ? 'opacity-0' : 'w-4'} ${isOpen || isScrolled ? 'text-black' : 'text-white'}`}></span>
            <span className={`h-[1px] bg-current transition-all duration-500 ${isOpen ? 'w-6 -translate-y-2 rotate-45' : 'w-5'} ${isOpen || isScrolled ? 'text-black' : 'text-white'}`}></span>
          </div>
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      <div
        className={`fixed inset-0 w-full h-screen bg-[#F9F9F7] z-[140] flex flex-col items-center justify-center transition-all duration-[0.8s] cubic-bezier(0.77, 0, 0.175, 1) ${
          isOpen ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-full pointer-events-none'
        }`}
      >
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-[30vw] font-serif text-black/[0.02] pointer-events-none select-none">
          AK
        </div>

        <div className="relative z-10 flex flex-col items-center gap-10">
          {navLinks.map((link, i) => (
            <a
              key={link.name}
              href={link.href}
              onClick={(e) => scrollToSection(e, link.href)}
              className={`text-4xl md:text-6xl font-serif text-black hover:text-brand transition-all duration-500 transform ${
                isOpen ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0'
              }`}
              style={{ transitionDelay: `${200 + i * 100}ms` }}
            >
              <span className="text-xs italic font-serif-alt mr-4 text-brand/60">{link.num}</span>
              {link.name}
            </a>
          ))}

          <div className={`mt-10 flex gap-8 transition-all duration-700 delay-500 ${isOpen ? 'opacity-100' : 'opacity-0'}`}>
            <a href="https://instagram.com/akfilmstudio" className="p-3 bg-white shadow-sm rounded-full text-brand"><Instagram size={24} /></a>
            <a href="mailto:hello@akfilmstudio.com" className="p-3 bg-white shadow-sm rounded-full text-brand"><Mail size={24} /></a>
          </div>
        </div>

        <div className="absolute bottom-12 flex flex-col items-center gap-2 opacity-40">
           <Heart size={14} className="text-brand fill-brand" />
           <span className="text-[9px] uppercase tracking-[0.4em]">Bregenz • Vorarlberg</span>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

