          <div className="aspect-portrait overflow-hidden shadow-2xl relative z-10 group">
             <img 
                src="https://images.unsplash.com/photo-1519741497674-611481863552?q=80&w=2940&auto=format&fit=crop" 
                alt="Emotional Moment" 
                className="w-full h-full object-cover grayscale-[0.3] group-hover:scale-105 transition-transform duration-[2s] ease-in-out"
             />
             <div className="absolute inset-0 bg-brand/5 mix-blend-multiply opacity-0 group-hover:opacity-100 transition-opacity duration-700"></div>
          </div>

          {/* Subtle Geometric Decor */}
          <div className="absolute -top-12 -left-12 w-48 h-48 border border-brand/20 -z-0"></div>
          <div className="absolute -bottom-10 -right-10 w-24 h-24 bg-brand/10 -z-0"></div>
        </div>

        {/* Narrative Text */}
        <div className="lg:col-span-6 space-y-10">
